import SwiftUI

/// Which agent a tab runs, as its logo: Claude's spark, Codex's cloud,
/// the other agents' own marks where LobeHub has them, and for any other
/// agent a monogram (its short name's first letter, in a colour its id
/// picks, so it's the same everywhere).
///
/// The marks' paths come from LobeHub's icon set, flattened to absolute
/// lines and cubic curves (`svgpath`: abs, unarc, unshort). Copyright (c)
/// 2023 LobeHub, MIT licence (github.com/lobehub/lobe-icons). The logos
/// themselves are their makers' trademarks, used to name their products.
public struct AgentMark: View {
    let harness: String
    var size: CGFloat
    /// One colour for the whole mark, instead of its own (on a squircle
    /// in its colours: `squircleFill`).
    var tint: Color?

    public init(harness: String, size: CGFloat = 16, tint: Color? = nil) {
        self.harness = harness
        self.size = size
        self.tint = tint
    }

    public var body: some View {
        mark
            .frame(width: size, height: size)
            .accessibilityElement(children: .ignore)
            .accessibilityLabel(Self.name(of: harness))
    }

    @ViewBuilder
    private var mark: some View {
        switch harness {
        case "claude":
            SVGShape(path: Self.claude)
                .fill(tint ?? Self.claudeOrange)
        case "codex":
            if let tint {
                SVGShape(path: Self.codex).fill(tint, style: FillStyle(eoFill: true))
            } else {
                SVGShape(path: Self.codex).fill(Self.codexGradient, style: FillStyle(eoFill: true))
            }
        case "gemini":
            SVGShape(path: Self.geminiPath).fill(paint(Self.geminiGradient), style: FillStyle(eoFill: true))
        case "qwen":
            SVGShape(path: Self.qwenPath).fill(paint(Color(red: 0x61 / 255, green: 0x5C / 255, blue: 0xED / 255)), style: FillStyle(eoFill: true))
        case "cursor":
            SVGShape(path: Self.cursorPath).fill(paint(Color.primary), style: FillStyle(eoFill: true))
        case "copilot":
            SVGShape(path: Self.copilotPath).fill(paint(Color.primary), style: FillStyle(eoFill: true))
        case "opencode":
            SVGShape(path: Self.opencodePath).fill(paint(Color.primary), style: FillStyle(eoFill: true))
        case "kilo":
            SVGShape(path: Self.kiloPath).fill(paint(Color.primary), style: FillStyle(eoFill: true))
        case "amp":
            SVGShape(path: Self.ampPath).fill(paint(Color.primary), style: FillStyle(eoFill: true))
        case "grok":
            SVGShape(path: Self.grokPath).fill(paint(Color.primary), style: FillStyle(eoFill: true))
        case "kimi":
            SVGShape(path: Self.kimiPath).fill(paint(Color.primary), style: FillStyle(eoFill: true))
        case "goose":
            SVGShape(path: Self.goosePath).fill(paint(Color.primary), style: FillStyle(eoFill: true))
        case "kiro":
            SVGShape(path: Self.kiroPath).fill(paint(Color(red: 0x90 / 255, green: 0x46 / 255, blue: 1)), style: FillStyle(eoFill: true))
        case "cline":
            SVGShape(path: Self.clinePath).fill(paint(Color.primary), style: FillStyle(eoFill: true))
        case "antigravity":
            SVGShape(path: Self.antigravityPath).fill(paint(Color(red: 0x31 / 255, green: 0x86 / 255, blue: 1)), style: FillStyle(eoFill: true))
        default:
            // A monogram: tinted, the letter alone (on squircleFill); else on
            // a pale square of the agent's colour.
            if let tint {
                Text(Self.name(of: harness).prefix(1).uppercased())
                    .font(.system(size: size * 0.8, weight: .bold, design: .rounded))
                    .foregroundStyle(tint)
            } else {
                let tint = Self.tint(of: harness)
                RoundedRectangle(cornerRadius: size * 0.28, style: .continuous)
                    .fill(tint.opacity(0.18))
                    .overlay {
                        Text(Self.name(of: harness).prefix(1).uppercased())
                            .font(.system(size: size * 0.62, weight: .bold, design: .rounded))
                            .foregroundStyle(tint)
                    }
                    .padding(size * 0.06)
            }
        }
    }

    /// The mark's own colours, or the tint.
    private func paint(_ own: some ShapeStyle) -> AnyShapeStyle { tint.map { AnyShapeStyle($0) } ?? AnyShapeStyle(own) }

    static let geminiGradient = LinearGradient(colors: [Color(red: 0x31 / 255, green: 0x86 / 255, blue: 1), Color(red: 0x9B / 255, green: 0x72 / 255, blue: 0xCB / 255)],
                                               startPoint: .topLeading, endPoint: .bottomTrailing)
    static let claudeOrange = Color(red: 0xD9 / 255, green: 0x77 / 255, blue: 0x57 / 255)
    static let codexGradient = LinearGradient(colors: [Color(red: 0xB1 / 255, green: 0xA7 / 255, blue: 1),
                                                       Color(red: 0x7A / 255, green: 0x9D / 255, blue: 1),
                                                       Color(red: 0x39 / 255, green: 0x41 / 255, blue: 1)],
                                              startPoint: .top, endPoint: .bottom)

    /// The squircle an agent's mark sits on in the colourful program-icons
    /// style (the mark in white): its own colours, else its monogram's.
    static func squircleFill(_ harness: String) -> AnyShapeStyle {
        switch harness {
        case "claude": AnyShapeStyle(claudeOrange)
        case "codex": AnyShapeStyle(codexGradient)
        case "gemini": AnyShapeStyle(geminiGradient)
        case "qwen": AnyShapeStyle(Color(red: 0x61 / 255, green: 0x5C / 255, blue: 0xED / 255))
        case "kiro": AnyShapeStyle(Color(red: 0x90 / 255, green: 0x46 / 255, blue: 1))
        case "antigravity": AnyShapeStyle(Color(red: 0x31 / 255, green: 0x86 / 255, blue: 1))
        // Marks drawn in the text colour: a dark grey.
        case "cursor", "copilot", "opencode", "kilo", "amp", "grok", "kimi", "goose", "cline":
            AnyShapeStyle(Color(red: 0x48 / 255, green: 0x48 / 255, blue: 0x4A / 255))
        default: AnyShapeStyle(tint(of: harness))
        }
    }

    /// The agent's name as people say it: "Claude", "Codex".
    @MainActor public static func name(of harness: String) -> String { AgentCatalog.shortName(of: harness) }

    /// A monogram's colour: picked by a hash of the id that's the same on
    /// every run and device (Swift's own hash isn't).
    static func tint(of harness: String) -> Color {
        let palette: [Color] = [.blue, .green, .indigo, .pink, .purple, .teal, .mint, .cyan, .brown, .red]
        let h = harness.unicodeScalars.reduce(UInt32(5381)) { ($0 &* 33) &+ $1.value }
        return palette[Int(h % UInt32(palette.count))]
    }

