/// A parsed path, fitted (aspect kept, centred) into whatever rect it's
/// drawn in.
struct SVGShape: Shape {
    let path: Path

    func path(in rect: CGRect) -> Path {
        let b = path.boundingRect
        guard b.width > 0, b.height > 0 else { return Path() }
        let s = min(rect.width / b.width, rect.height / b.height)
        let dx = rect.midX - b.midX * s, dy = rect.midY - b.midY * s
        return path.applying(CGAffineTransform(a: s, b: 0, c: 0, d: s, tx: dx, ty: dy))
    }
}

/// SVG path data with absolute M, L, H, V, C and Z only (what `svgpath`'s
/// abs().unarc().unshort() leaves), enough for the marks above.
enum SVGPath {
    /// No exponents or relative commands: `svgpath` writes neither here.
    static func parse(_ d: String) -> Path {
        var tokens: [Substring] = []
        var i = d.startIndex
        while i < d.endIndex {
            let c = d[i]
            if c.isLetter {
                tokens.append(d[i...i])
                i = d.index(after: i)
            } else if c.isNumber || c == "-" || c == "." {
                var j = d.index(after: i)
                var dot = c == "."
                while j < d.endIndex {
                    let n = d[j]
                    if n.isNumber { j = d.index(after: j); continue }
                    if n == ".", !dot { dot = true; j = d.index(after: j); continue }
                    break
                }
                tokens.append(d[i..<j])
                i = j
            } else {
                i = d.index(after: i)
            }
        }

        var p = Path()
        var command: Character = "M"
        var current = CGPoint.zero
        var start = CGPoint.zero
        var k = 0
        func number() -> CGFloat {
            defer { k += 1 }
            return k < tokens.count ? CGFloat(Double(tokens[k]) ?? 0) : 0
        }
        func point() -> CGPoint { CGPoint(x: number(), y: number()) }
        while k < tokens.count {
            if let c = tokens[k].first, c.isLetter {
                command = c
                k += 1
                if c == "Z" || c == "z" { p.closeSubpath(); current = start; continue }
            }
            switch command {
            case "M":
                current = point()
                p.move(to: current)
                start = current
                command = "L" // further pairs are lines
            case "L":
                current = point()
                p.addLine(to: current)
            case "H":
                current.x = number()
                p.addLine(to: current)
            case "V":
                current.y = number()
                p.addLine(to: current)
            case "C":
                let c1 = point(), c2 = point()
                current = point()
                p.addCurve(to: current, control1: c1, control2: c2)
            default:
                k += 1 // unsupported: skip
            }
        }
        return p
    }
}
